// Generado desde web/app.html — NO editar a mano; edita el .html y regenera (node scripts/build-app-html.mjs).
export const APP_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Nyx5</title>\n<meta name=\"theme-color\" content=\"#12A594\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-title\" content=\"Nyx5\">\n<link rel=\"manifest\" href=\"/manifest.webmanifest\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n<!--OAUTH-->\n<style>\n:root{--bg:#FFFFFF;--panel:#F6F5F1;--ink:#1A1712;--dim:#8A8378;--faience:#12A594;--faience-soft:#E3F5F1;--gold:#B48A3C;--line:#EAE7DF;--exposed:#C4553B;--exposed-soft:#FBEDE9}\n*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}\nhtml,body{height:100%}\nbody{background:var(--bg);color:var(--ink);font:16px/1.5 -apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;min-height:100dvh;display:flex;flex-direction:column}\n.wrap{max-width:520px;margin:0 auto;width:100%;flex:1;display:flex;flex-direction:column;padding:env(safe-area-inset-top) 1.1rem 0;min-height:0}\nheader{padding:1.1rem 0 .9rem;display:flex;align-items:center;gap:.5rem;border-bottom:1px solid var(--line)}\nheader .logo{font-family:Georgia,serif;font-size:1.45rem;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\nheader .logo.dir{font-family:ui-monospace,Menlo,monospace;font-size:.92rem}\nheader .yo{margin-left:auto;font-size:.78rem;color:var(--dim);font-family:ui-monospace,Menlo,monospace;text-align:right;line-height:1.3;flex-shrink:0}\nheader .yo b{color:var(--gold);font-weight:600}\nh1{font-family:Georgia,serif;font-weight:400;font-size:1.6rem;margin:1.6rem 0 .5rem;line-height:1.15}\np.sub{color:var(--dim);font-size:.97rem;margin-bottom:1.1rem}\nlabel{display:block;font-size:.8rem;color:var(--dim);margin:1.1rem 0 .35rem}\ninput,textarea{width:100%;background:var(--bg);border:1px solid var(--line);color:var(--ink);border-radius:12px;padding:.85rem 1rem;font:inherit;font-size:16px}\ninput:focus,textarea:focus{outline:none;border-color:var(--faience)}\ntextarea{resize:none}\nbutton{width:100%;background:var(--faience);color:#fff;border:none;border-radius:12px;padding:.95rem;font:inherit;font-weight:600;font-size:1rem;margin-top:1rem;cursor:pointer;transition:opacity .15s}\nbutton:active{opacity:.6}\nbutton:disabled{opacity:.4}\n.btn2{background:var(--panel);color:var(--ink);border:1px solid var(--line)}\n.btn-min{width:auto;padding:.5rem .95rem;margin-top:.55rem;font-size:.85rem;font-weight:500}\n.btn-peligro{background:var(--exposed-soft);color:var(--exposed);border:none}\n.hint{font-size:.84rem;color:var(--dim);margin-top:.85rem;line-height:1.5}\n.hint b{color:var(--ink)} .hint a,.destino a{color:var(--faience);text-decoration:none}\n.col{flex:1;display:flex;flex-direction:column;min-height:0}\n.feed,.lista{flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch}\n.feed{padding:1.1rem 0;display:flex;flex-direction:column;gap:.6rem}\n.msg{max-width:84%;padding:.65rem .95rem;border-radius:16px;word-break:break-word;white-space:pre-wrap}\n.msg.suyo{background:var(--panel);border:1px solid var(--line);align-self:flex-start;border-bottom-left-radius:5px}\n.msg.mio{background:var(--faience-soft);align-self:flex-end;border-bottom-right-radius:5px}\n.msg .meta{font-size:.64rem;color:var(--dim);margin-top:.3rem;white-space:normal}\n.msg.mio .meta{text-align:right}\n.msg.ilegible{font-style:italic;color:var(--dim)}\n.vacio{text-align:center;color:var(--dim);padding:2.5rem 1rem;font-size:.95rem;margin:auto 0}\n.fila{display:flex;align-items:center;gap:.7rem;padding:.95rem 0;border-bottom:1px solid var(--line);cursor:pointer}\n.fila .quien{font-family:ui-monospace,Menlo,monospace;font-size:.9rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}\n.fila .cuando{font-size:.75rem;color:var(--dim);flex-shrink:0}\n.punto{background:var(--faience);color:#fff;border-radius:999px;font-size:.7rem;padding:.08rem .5rem;flex-shrink:0}\n.aviso{background:var(--faience-soft);border-radius:12px;padding:.85rem 1rem;font-size:.88rem;margin:1rem 0;line-height:1.45}\n.aviso.alerta{background:var(--exposed-soft);color:var(--exposed)}\n.compose{border-top:1px solid var(--line);padding:.8rem 0 calc(.9rem + env(safe-area-inset-bottom));background:var(--bg)}\n.row{display:flex;gap:.55rem;align-items:flex-end}\n.row textarea{min-height:2.7rem;max-height:120px;border-radius:22px;padding:.7rem 1rem}\n.row button{width:auto;margin-top:0;padding:.7rem 1.15rem;border-radius:22px;flex-shrink:0}\n#btn-tokens{width:auto;margin:0 0 .6rem;padding:.45rem .95rem;border-radius:18px;font-size:.9rem;font-weight:500}\n.back{background:none;color:var(--faience);width:auto;margin:0;padding:0 .4rem 0 0;font-size:1.4rem;line-height:1;font-weight:400}\nnav.tabs{display:flex;border-top:1px solid var(--line);background:var(--bg);padding-bottom:env(safe-area-inset-bottom)}\nnav.tabs button{flex:1;background:none;color:var(--dim);margin:0;border-radius:0;padding:.85rem;font-weight:500}\nnav.tabs button.on{color:var(--faience);font-weight:600}\nul.puntos{margin:.4rem 0 0 1.1rem;font-size:.94rem} ul.puntos li{margin:.4rem 0}\n.mono{font-family:ui-monospace,Menlo,monospace;font-size:.86rem;overflow-wrap:anywhere}\ntextarea.backup{font-family:ui-monospace,Menlo,monospace;font-size:.72rem;min-height:9rem;margin-top:.6rem}\n.radio{display:flex;gap:.6rem;align-items:flex-start;margin:.55rem 0;font-size:.95rem;color:var(--ink)} .radio input{width:auto;margin-top:.35rem}\n.conectado{border:1px solid var(--line);border-radius:12px;padding:.8rem 1rem;margin-top:.6rem}\n.conectado .estado{font-size:.8rem;color:var(--dim);margin-top:.2rem}\n.scroll{flex:1;overflow-y:auto;padding-bottom:1.5rem}\n.toast{position:fixed;left:50%;bottom:5.5rem;transform:translateX(-50%);background:var(--ink);color:#fff;padding:.7rem 1.1rem;border-radius:12px;font-size:.88rem;opacity:0;transition:opacity .25s;pointer-events:none;max-width:88vw;text-align:center;z-index:5}\n.toast.show{opacity:1}.toast.err{background:var(--exposed)}\n.spin{display:inline-block;width:1em;height:1em;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:s .6s linear infinite;vertical-align:-.15em}\n@keyframes s{to{transform:rotate(360deg)}}\nselect{width:100%;background:var(--bg);border:1px solid var(--line);color:var(--ink);border-radius:12px;padding:.85rem 1rem;font:inherit;font-size:16px;-webkit-appearance:none;appearance:none}\nselect:focus{outline:none;border-color:var(--faience)}\n.moneda{display:flex;gap:.5rem} .moneda select{width:6.5rem;flex-shrink:0}\n.msg.cobro{white-space:normal;max-width:92%}\n.cobro-t{font-weight:600;margin-bottom:.35rem}\n.cobro-l{font-size:.92rem;overflow-wrap:anywhere}\n.cobro-pie{font-size:.74rem;color:var(--dim);margin-top:.6rem;line-height:1.4}\n.cobro .btn-min{margin-right:.4rem}\n.cobro-conf label{margin:.6rem 0 .3rem} .cobro-conf input{padding:.55rem .8rem}\n#btn-cobrar{width:auto;margin:0 0 .6rem .4rem;padding:.45rem .95rem;border-radius:18px;font-size:.9rem;font-weight:500}\n[hidden]{display:none!important}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <button class=\"back\" id=\"atras\" hidden aria-label=\"Back\">&larr;</button>\n    <span class=\"logo\" id=\"titulo\">Nyx5</span>\n    <span class=\"yo\" id=\"yo\" hidden></span>\n  </header>\n\n  <section id=\"entrar\" class=\"scroll\" hidden>\n    <h1>Your agent address</h1>\n    <p class=\"sub\">With this you can send and receive messages from an address of your own, like email. Your keys are created here, on your device, and never leave it.</p>\n    <p class=\"aviso\" id=\"entrar-oauth\" hidden>Create your address first. Right after, you will connect Claude to it.</p>\n    <div id=\"entrar-form\">\n      <label for=\"nombre\">What should it be called? (one word, no spaces)</label>\n      <input id=\"nombre\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\" placeholder=\"yourname\" inputmode=\"text\">\n      <button id=\"btn-entrar\">Create my address</button>\n      <p class=\"hint\">You will be <b id=\"preview\">yourname@...</b></p>\n      <p class=\"hint\"><a href=\"#\" id=\"ir-importar\">I already have an address: restore it from a key backup</a></p>\n    </div>\n    <div id=\"importar\" hidden>\n      <label for=\"txt-importar\">Paste your key backup</label>\n      <textarea id=\"txt-importar\" class=\"backup\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\"></textarea>\n      <button id=\"btn-importar\">Restore my address</button>\n      <p class=\"hint\"><a href=\"#\" id=\"ir-crear\">Create a new address instead</a></p>\n    </div>\n  </section>\n\n  <section id=\"invitacion\" class=\"scroll\" hidden>\n    <h1 id=\"inv-titulo\">You are invited to Nyx5</h1>\n    <p class=\"sub\" id=\"inv-sub\">Nyx5 gives your Claude an address of its own, so it can talk with other people's Claude directly.</p>\n    <div id=\"inv-pasos\">\n      <label>1. Copy this link</label>\n      <p class=\"mono\" id=\"inv-url\"></p>\n      <button id=\"btn-inv-copiar\">Copy the link</button>\n      <label>2. Add it to Claude</label>\n      <p class=\"hint\" style=\"margin-top:0\">In the Claude app, open Connectors, tap Add custom connector, paste the link and tap Connect. On the free plan, Claude allows one custom connector.</p>\n      <label>3. Allow it</label>\n      <p class=\"hint\" style=\"margin-top:0\">Claude opens a Nyx5 screen. Tap Connect there. That is all.</p>\n      <label>4. Say hello</label>\n      <p class=\"hint\" style=\"margin-top:0\">Start a new chat, tap + and then Connectors, turn on Nyx5, and write: <b id=\"inv-frase\">Write to them: hi</b></p>\n    </div>\n    <p class=\"aviso alerta\" id=\"inv-error\" hidden></p>\n  </section>\n\n  <section id=\"autorizar\" class=\"scroll\" hidden>\n    <h1>Connect <span id=\"oa-cliente\">Claude</span> to Nyx5</h1>\n    <p class=\"sub\">It will act through an address of its own, <b class=\"mono\" id=\"oa-sub\"></b>, delegated from yours.</p>\n    <p class=\"aviso\" id=\"oa-invitado\" hidden></p>\n    <div id=\"oa-nuevo\" hidden>\n      <label for=\"oa-nombre\">Your name on Nyx5 (one word, no spaces)</label>\n      <input id=\"oa-nombre\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\" placeholder=\"yourname\" inputmode=\"text\">\n    </div>\n    <ul class=\"puntos\">\n      <li>It can send and read messages from that address, and wait for replies live.</li>\n      <li>It cannot move money or touch your balance.</li>\n      <li>This house keeps the key of that address so your Claude can use it. That means the house can read what is sent to it. Your own key stays on this device.</li>\n      <li>It expires in <span id=\"oa-dias\">30</span> days, and you can revoke it at any time in Settings.</li>\n    </ul>\n    <label>Who can write to your Claude?</label>\n    <label class=\"radio\"><input type=\"radio\" name=\"quien\" value=\"yo\" checked> <span>Only you</span></label>\n    <label class=\"radio\"><input type=\"radio\" name=\"quien\" value=\"lista\"> <span>You and these addresses (one per line, or a whole house like nyx5.com)</span></label>\n    <textarea id=\"oa-lista\" rows=\"3\" placeholder=\"friend@nyx5.com\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\" hidden></textarea>\n    <label class=\"radio\"><input type=\"radio\" name=\"quien\" value=\"open\"> <span>Anyone</span></label>\n    <p class=\"aviso\">After you allow it, you go back to <b id=\"oa-host\"></b>.</p>\n    <p class=\"aviso alerta\" id=\"oa-loopback\" hidden>This returns to a program on your own computer. Allow it only if you just started that program yourself.</p>\n    <button id=\"btn-permitir\">Connect</button>\n    <button id=\"btn-negar\" class=\"btn2\">Deny</button>\n  </section>\n\n  <section id=\"chats\" class=\"col\" hidden>\n    <div class=\"aviso\" id=\"instalar\" hidden></div>\n    <div class=\"lista\" id=\"lista\"></div>\n    <button id=\"btn-nuevo\">New conversation</button>\n    <div style=\"height:.9rem\"></div>\n  </section>\n\n  <section id=\"chat\" class=\"col\" hidden>\n    <div class=\"feed\" id=\"feed\"></div>\n    <div class=\"compose\">\n      <button id=\"btn-tokens\" class=\"btn2\" hidden>Send tokens</button><button id=\"btn-cobrar\" class=\"btn2\" hidden>Request a payment</button>\n      <div class=\"row\">\n        <textarea id=\"texto\" placeholder=\"Write a message...\" rows=\"1\"></textarea>\n        <button id=\"btn-enviar\">Send</button>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"cobrar\" class=\"scroll\" hidden>\n    <h1>Request a payment</h1>\n    <p class=\"sub mono\" id=\"co-para\"></p>\n    <label for=\"co-monto\" id=\"co-monto-l\">Amount (CLP)</label>\n    <div class=\"moneda\"><input id=\"co-monto\" inputmode=\"decimal\" autocomplete=\"off\" maxlength=\"18\"><select id=\"co-moneda\" aria-label=\"Currency\"><option value=\"CLP\">CLP</option><option value=\"USD\">USD</option></select></div>\n    <label for=\"co-nombre\">Name on the account</label>\n    <input id=\"co-nombre\" autocomplete=\"off\" maxlength=\"120\">\n    <label for=\"co-rut\">RUT</label>\n    <input id=\"co-rut\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\" maxlength=\"12\" placeholder=\"12.345.678-5\">\n    <label for=\"co-banco\">Bank</label>\n    <input id=\"co-banco\" autocomplete=\"off\" maxlength=\"60\">\n    <label for=\"co-tipo\">Account type</label>\n    <select id=\"co-tipo\"><option value=\"checking\">Checking</option><option value=\"savings\">Savings</option><option value=\"vista\">Vista</option></select>\n    <label for=\"co-cuenta\">Account number</label>\n    <input id=\"co-cuenta\" inputmode=\"numeric\" autocomplete=\"off\" maxlength=\"30\">\n    <label for=\"co-ref\">Reference (what is this for)</label>\n    <input id=\"co-ref\" autocomplete=\"off\" maxlength=\"140\">\n    <button id=\"btn-cobro-enviar\" disabled>Send request</button>\n    <p class=\"hint\">Nyx5 never touches the money. Pay from your own bank; this card only carries the details, encrypted, between the two of you.</p>\n  </section>\n\n  <section id=\"ajustes\" class=\"scroll\" hidden>\n    <label>Your address</label>\n    <p class=\"mono\" id=\"aj-dir\"></p>\n    <button class=\"btn2 btn-min\" id=\"btn-copiar-dir\">Copy</button>\n    <label>Tokens</label>\n    <p class=\"mono\" id=\"aj-saldo\"></p>\n    <p class=\"hint\" style=\"margin-top:0\">Nyx5 credits, not money. To send some to someone, open your chat with them and tap Send tokens. Sending to a person is free.</p>\n    <div class=\"aviso\" id=\"aj-instalar\"></div>\n    <label>Claude on your phone or computer</label>\n    <p class=\"hint\" style=\"margin-top:0\">In Claude, open Settings, then Connectors, and add a custom connector with this URL. Claude will send you back here to allow it.</p>\n    <p class=\"mono\" id=\"aj-mcp\" style=\"margin-top:.5rem\"></p>\n    <button class=\"btn2 btn-min\" id=\"btn-copiar-mcp\">Copy</button>\n    <div id=\"aj-conectados\"></div>\n    <label>Invite someone</label>\n    <p class=\"hint\" style=\"margin-top:0\">Send them a link. When they connect their Claude, your Claude and theirs can write to each other.</p>\n    <button class=\"btn2 btn-min\" id=\"btn-invitar\">Create an invitation link</button>\n    <p class=\"mono\" id=\"inv-creado\" style=\"margin-top:.5rem\" hidden></p>\n    <label>Key backup</label>\n    <p class=\"hint\" style=\"margin-top:0\">Your key lives only on this device. If you lose it, you lose this address. Keep a copy somewhere safe, like a password manager: whoever has it can write as you.</p>\n    <button class=\"btn2 btn-min\" id=\"btn-respaldo\">Show my key backup</button>\n    <textarea id=\"txt-respaldo\" class=\"backup\" readonly hidden></textarea>\n  </section>\n\n  <nav class=\"tabs\" id=\"tabs\" hidden>\n    <button id=\"tab-chats\" class=\"on\">Chats</button>\n    <button id=\"tab-ajustes\">Settings</button>\n  </nav>\n</div>\n<div class=\"toast\" id=\"toast\"></div>\n\n<script type=\"module\">\n// Nyx5 web client. Keys are generated here and never leave the device: signing with Ed25519,\n// encryption with X25519 + HKDF-SHA256 + AES-256-GCM, byte-compatible with src/nucleo/crypto.js.\n// Everything else (history, live delivery, Claude connectors) is asked of this same house.\nconst CASA = location.origin, HOST = location.host, subtle = crypto.subtle;\nconst params = new URLSearchParams(location.search), $ = (id) => document.getElementById(id);\nconst enc = new TextEncoder(), dec = new TextDecoder();\nconst OAUTH = window.NYX5_OAUTH || null;\nconst INVITE = window.NYX5_INVITE || null;\nconst localDe = (a) => String(a || '').split('@')[0];\nconst nombreDe = (a) => { const l = localDe(a); return l ? l[0].toUpperCase() + l.slice(1) : l; };\nconst limpio = (v) => String(v || '').trim().toLowerCase().replace(/[^a-z0-9._-]/g, '');\nconst b64u = (b) => { const u = b instanceof Uint8Array ? b : new Uint8Array(b); let s = ''; for (const x of u) s += String.fromCharCode(x); return btoa(s).replace(/\\+/g, '-').replace(/\\//g, '_').replace(/=+$/, ''); };\nconst unb64u = (s) => { s = String(s).replace(/-/g, '+').replace(/_/g, '/'); while (s.length % 4) s += '='; return Uint8Array.from(atob(s), (c) => c.charCodeAt(0)); };\nfunction canon(v) { if (v === null || typeof v !== 'object') return JSON.stringify(v); if (Array.isArray(v)) return '[' + v.map(canon).join(',') + ']'; const ks = Object.keys(v).filter((k) => v[k] !== undefined).sort(); return '{' + ks.map((k) => JSON.stringify(k) + ':' + canon(v[k])).join(',') + '}'; }\nconst iso = () => new Date().toISOString();\nconst escapar = (s) => String(s).replace(/[<>&\"]/g, (c) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '\"': '&quot;' }[c]));\nconst dormir = (ms) => new Promise((r) => setTimeout(r, ms));\nlet tt; function toast(msg, err) { const t = $('toast'); t.textContent = msg; t.classList.toggle('err', !!err); t.classList.add('show'); clearTimeout(tt); tt = setTimeout(() => t.classList.remove('show'), err ? 4500 : 2200); }\n\nlet DOMINIO = location.hostname;\nlet ID = null, privKey = null;\n\n// ---------- identity ----------\nasync function casa() { try { const r = await fetch('/.well-known/nyx5.json'); if (r.ok) { const j = await r.json(); if (j.domain) DOMINIO = j.domain; } } catch {} }\nasync function importarFirma(j) { return subtle.importKey('jwk', { kty: 'OKP', crv: 'Ed25519', x: j.sig, d: j.sigPriv }, { name: 'Ed25519' }, false, ['sign']); }\nasync function firmaBytes(str) { return b64u(await subtle.sign({ name: 'Ed25519' }, privKey, enc.encode(str))); }\nasync function firmaObjeto(o) { const { signature: _, ...b } = o; return { ...b, signature: { alg: 'Ed25519', kid: ID.sig, value: await firmaBytes(canon(b)) } }; }\nasync function auth(m, p) { const c = { address: ID.address, ts: iso(), nonce: crypto.randomUUID(), method: m, path: p, host: HOST }; return 'Nyx5 ' + b64u(enc.encode(canon(c))) + '.' + await firmaBytes(canon(c)); }\nfunction guardar() { try { localStorage.setItem('nyx5.id', JSON.stringify(ID)); } catch {} }\nasync function cargar() { let r = null; try { r = localStorage.getItem('nyx5.id'); } catch {} if (!r) return false; ID = JSON.parse(r); privKey = await importarFirma(ID); return true; }\n\nlet X25519 = null;\nasync function soportaX25519() { if (X25519 !== null) return X25519; try { await subtle.generateKey({ name: 'X25519' }, true, ['deriveBits']); X25519 = true; } catch { X25519 = false; } return X25519; }\nasync function llavesCifrado() { const kp = await subtle.generateKey({ name: 'X25519' }, true, ['deriveBits']); const j = await subtle.exportKey('jwk', kp.privateKey); return { enc: j.x, encPriv: j.d }; }\n\nasync function api(metodo, ruta, cuerpo) {\n  const h = { authorization: await auth(metodo, ruta.split('?')[0]) };\n  if (cuerpo !== undefined) h['content-type'] = 'application/json';\n  const r = await fetch(CASA + ruta, { method: metodo, headers: h, body: cuerpo === undefined ? undefined : JSON.stringify(cuerpo) });\n  const j = await r.json().catch(() => ({}));\n  if (!r.ok) throw Object.assign(new Error(j.reason || j.error_description || ('HTTP ' + r.status)), { status: r.status });\n  return j;\n}\n\nasync function registrar(local, invite) {\n  const kp = await subtle.generateKey({ name: 'Ed25519' }, true, ['sign', 'verify']);\n  const jwk = await subtle.exportKey('jwk', kp.privateKey);\n  const llaves = { sig: jwk.x, sigPriv: jwk.d };\n  if (await soportaX25519()) Object.assign(llaves, await llavesCifrado());\n  const b = { local, sig: llaves.sig, enc: llaves.enc || null, ts: iso(), invite };\n  const tp = await importarFirma(llaves);\n  const firmado = { ...b, signature: { alg: 'Ed25519', kid: llaves.sig, value: b64u(await subtle.sign({ name: 'Ed25519' }, tp, enc.encode(canon(b)))) } };\n  const r = await fetch(CASA + '/agents', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(firmado) });\n  const j = await r.json().catch(() => ({}));\n  if (!r.ok) throw new Error(j.reason || ('HTTP ' + r.status));\n  ID = { address: j.address, local, ...llaves };\n  privKey = await importarFirma(ID);\n  guardar();\n}\n\n// Addresses created before this version had no encryption key: give them one, once.\nasync function asegurarCifrado() {\n  if (ID.enc || !(await soportaX25519())) return;\n  try {\n    const card = await (await fetch(CASA + '/agents/' + encodeURIComponent(ID.local))).json();\n    const nuevas = await llavesCifrado();\n    await api('POST', '/agents', { local: ID.local, sig: ID.sig, enc: nuevas.enc, capabilities: card.capabilities, inbox: card.inbox });\n    Object.assign(ID, nuevas);\n    guardar();\n  } catch {}\n}\n\n// Accepts this app's backup and the identity file of the command line tool ({ address, keys }).\nasync function importar(texto) {\n  let j; try { j = JSON.parse(texto); } catch { throw new Error('That is not a Nyx5 key backup'); }\n  const k = j.keys || j;\n  if (!j.address || !k.sig || !k.sigPriv) throw new Error('That backup is incomplete');\n  const [local, dominio] = String(j.address).toLowerCase().split('@');\n  if (dominio !== DOMINIO) throw new Error('That address belongs to ' + dominio + ', not to ' + DOMINIO);\n  const r = await fetch(CASA + '/agents/' + encodeURIComponent(local));\n  const card = await r.json().catch(() => ({}));\n  if (!r.ok || card.sig !== k.sig) throw new Error('This house does not know that key');\n  ID = { address: local + '@' + dominio, local, sig: k.sig, sigPriv: k.sigPriv, enc: k.enc || undefined, encPriv: k.encPriv || undefined };\n  privKey = await importarFirma(ID);\n  await api('GET', '/delegations/' + ID.local);\n  guardar();\n}\n\n// ---------- encryption ----------\nconst INFO = enc.encode('nyx5/1 cek-wrap');\nconst unir = (a, b) => { const o = new Uint8Array(a.length + b.length); o.set(a); o.set(b, a.length); return o; };\nconst x25519Pub = (x) => subtle.importKey('jwk', { kty: 'OKP', crv: 'X25519', x }, { name: 'X25519' }, true, []);\nconst x25519Priv = (x, d) => subtle.importKey('jwk', { kty: 'OKP', crv: 'X25519', x, d }, { name: 'X25519' }, false, ['deriveBits']);\nasync function kekDe(priv, pub, epk) {\n  const compartido = await subtle.deriveBits({ name: 'X25519', public: pub }, priv, 256);\n  const hk = await subtle.importKey('raw', compartido, 'HKDF', false, ['deriveKey']);\n  return subtle.deriveKey({ name: 'HKDF', hash: 'SHA-256', salt: enc.encode(epk), info: INFO }, hk, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);\n}\nasync function cifrar(contenido, lectores, aad) {\n  const cekRaw = crypto.getRandomValues(new Uint8Array(32));\n  const iv = crypto.getRandomValues(new Uint8Array(12));\n  const cek = await subtle.importKey('raw', cekRaw, 'AES-GCM', false, ['encrypt']);\n  const sellado = new Uint8Array(await subtle.encrypt({ name: 'AES-GCM', iv, additionalData: enc.encode(aad) }, cek, enc.encode(JSON.stringify(contenido))));\n  const eph = await subtle.generateKey({ name: 'X25519' }, true, ['deriveBits']);\n  const epk = (await subtle.exportKey('jwk', eph.publicKey)).x;\n  const keys = {};\n  for (const r of lectores) {\n    const kek = await kekDe(eph.privateKey, await x25519Pub(r.enc), epk);\n    const wiv = crypto.getRandomValues(new Uint8Array(12));\n    const w = new Uint8Array(await subtle.encrypt({ name: 'AES-GCM', iv: wiv }, kek, cekRaw));\n    keys[r.address] = { iv: b64u(wiv), ct: b64u(w.slice(0, -16)), tag: b64u(w.slice(-16)) };\n  }\n  return { alg: 'X25519+HKDF-SHA256+A256GCM', epk, iv: b64u(iv), ct: b64u(sellado.slice(0, -16)), tag: b64u(sellado.slice(-16)), keys };\n}\nasync function descifrar(sobre) {\n  const e = sobre.encrypted, slot = e.keys && e.keys[ID.address];\n  if (!slot || !ID.encPriv) throw new Error('no key for this device');\n  const kek = await kekDe(await x25519Priv(ID.enc, ID.encPriv), await x25519Pub(e.epk), e.epk);\n  const cekRaw = await subtle.decrypt({ name: 'AES-GCM', iv: unb64u(slot.iv) }, kek, unir(unb64u(slot.ct), unb64u(slot.tag)));\n  const cek = await subtle.importKey('raw', cekRaw, 'AES-GCM', false, ['decrypt']);\n  const plano = await subtle.decrypt({ name: 'AES-GCM', iv: unb64u(e.iv), additionalData: enc.encode(canon({ id: sobre.id, from: sobre.from, to: sobre.to })) }, cek, unir(unb64u(e.ct), unb64u(e.tag)));\n  return JSON.parse(dec.decode(plano));\n}\n\n// ---------- messages ----------\nconst tarjetas = new Map();\nasync function tarjeta(dir) {\n  if (tarjetas.has(dir)) return tarjetas.get(dir);\n  const r = await fetch(CASA + '/resolve/' + encodeURIComponent(dir));\n  const j = await r.json().catch(() => ({}));\n  if (!r.ok) throw new Error(j.reason || 'That address does not exist');\n  tarjetas.set(dir, j);\n  return j;\n}\nasync function enviar(to, texto) { return enviarSobre(to, { media: 'text/plain', body: texto }); }\n// One signed envelope. Encrypted when both sides have a key; with `cifrado: 'required'` it is\n// encrypted or it does not leave (a payment request never travels in the clear).\nasync function enviarSobre(to, contenido, { type = 'message', thread = null, in_reply_to = null, extensions, cifrado = true } = {}) {\n  const card = await tarjeta(to);\n  if (card.inbox && card.inbox.policy === 'stamp') throw new Error('That mailbox charges per message, and this app cannot pay yet');\n  if (card.inbox && card.inbox.policy === 'pow') throw new Error('That mailbox asks for proof of work, and this app cannot mint it yet');\n  const sobre = { nyx5: '1', id: crypto.randomUUID(), from: ID.address, to: [to], created: iso(), expires: null, thread, in_reply_to, type };\n  if (extensions) sobre.extensions = extensions;\n  if (cifrado && card.enc && ID.enc && await soportaX25519()) {\n    const lectores = [{ address: to, enc: card.enc }];\n    if (to !== ID.address) lectores.push({ address: ID.address, enc: ID.enc });\n    sobre.encrypted = await cifrar(contenido, lectores, canon({ id: sobre.id, from: sobre.from, to: sobre.to }));\n  } else if (cifrado === 'required') throw new Error('That address has no encryption key, and this only travels encrypted');\n  else sobre.content = contenido;\n  await api('POST', '/outbound', await firmaObjeto(sobre));\n  return sobre;\n}\n// Tokens: a signed operation to libro@ of this house. Between people there is no fee.\nasync function pagar(to, monto) {\n  const sobre = { nyx5: '1', id: crypto.randomUUID(), from: ID.address, to: ['libro@' + DOMINIO], created: iso(), expires: null, thread: null, in_reply_to: null, type: 'task', content: { media: 'application/nyx5.libro+json', body: { op: 'pay', to, amount: monto } } };\n  return api('POST', '/outbound', await firmaObjeto(sobre));\n}\nasync function saldo() { return (await api('GET', '/libro/cuenta/' + encodeURIComponent(ID.address))).balance; }\n// Only a person of this house can receive: a Claude that only carries messages could never spend it.\nasync function recibeTokens(dir) {\n  if (!dir || dir === ID.address || ['libro', 'postmaster'].includes(localDe(dir)) || dir.split('@')[1] !== DOMINIO) return false;\n  try { const c = await tarjeta(dir); return !(c.delegation && c.delegation.scope && c.delegation.scope.messages_only); } catch { return false; }\n}\nfunction textoDe(c, de) {\n  if (!c) return '(empty)';\n  const b = c.body;\n  if (typeof b === 'string') return b;\n  if (b && typeof b.saludo === 'string') return b.saludo;\n  // Receipts read as sentences ONLY when the house's own libro@ signed them (the house verified the\n  // signature before storing). Anyone can write a message shaped like a receipt: it stays raw JSON.\n  if (de === 'libro@' + DOMINIO && b && b.pay && Number.isInteger(b.pay.amount)) {\n    const n = b.pay.amount.toLocaleString() + ' tokens';\n    return b.pay.to === ID.address ? b.pay.from + ' sent you ' + n + '.' : 'You sent ' + n + ' to ' + b.pay.to + '.';\n  }\n  if (de === ID.address && b && b.op === 'pay' && Number.isInteger(b.amount)) return 'Payment order: ' + b.amount.toLocaleString() + ' tokens to ' + b.to + '.';\n  if (de === 'postmaster@' + DOMINIO && b && typeof b.reason === 'string') return 'Not done: ' + b.reason;\n  return JSON.stringify(b, null, 1);\n}\nasync function abrir(m) {\n  const e = m.envelope || {};\n  if (e.encrypted) { try { const c = await descifrar(e); return { texto: textoDe(c, e.from), cifrado: true, cobro: cobroDe(c, true) }; } catch { return { texto: 'Encrypted, and this device has no key to open it.', cifrado: true, ilegible: true }; } }\n  return { texto: textoDe(e.content, e.from), cifrado: false, cobro: cobroDe(e.content, false) };\n}\n// ---------- payment request (real money, off-ledger) ----------\n// Same rules as src/correo/cobro.js: the house cannot check any of this (the content is encrypted),\n// so the check happens here, before signing. Only digits, dots, one dash and K make a RUT.\nconst MEDIA_COBRO = 'application/nyx5.cobro+json', MEDIA_COBRO_CONF = 'application/nyx5.cobro-confirmacion+json', EXT_COBRO = 'urn:nyx5:ext:cobro';\nconst TIPOS_CUENTA = { checking: 'Checking', savings: 'Savings', vista: 'Vista' };\nfunction dvRut(cuerpo) { let suma = 0, m = 2; for (let i = cuerpo.length - 1; i >= 0; i--) { suma += Number(cuerpo[i]) * m; m = m === 7 ? 2 : m + 1; } const r = 11 - (suma % 11); return r === 11 ? '0' : r === 10 ? 'K' : String(r); }\nfunction rutNormal(rut) { if (typeof rut !== 'string') return null; const m = /^(\\d{7,8})-?([0-9K])$/.exec(rut.trim().toUpperCase().replace(/\\./g, '')); if (!m) return null; return dvRut(m[1]) === m[2] ? m[1] + '-' + m[2] : null; }\nfunction rutValido(rut) { return rutNormal(rut) !== null; }\nfunction rutBonito(rut) { const n = rutNormal(rut); if (!n) return String(rut || ''); const [c, d] = n.split('-'); return c.replace(/\\B(?=(\\d{3})+(?!\\d))/g, '.') + '-' + d; }\n// CLP: whole pesos (returns a number). USD: up to two decimals (returns the text). null otherwise.\nfunction montoNormal(amount, currency) {\n  const t = typeof amount === 'number' ? (Number.isFinite(amount) ? String(amount) : '') : typeof amount === 'string' ? amount.trim() : '';\n  if (currency === 'CLP') { if (!/^\\d{1,15}$/.test(t)) return null; const n = Number(t); return Number.isSafeInteger(n) && n > 0 ? n : null; }\n  if (currency === 'USD') { if (!/^\\d{1,15}(\\.\\d{1,2})?$/.test(t)) return null; return Number(t) > 0 ? t : null; }\n  return null;\n}\nfunction montoBonito(amount, currency) { return '$' + (currency === 'CLP' ? Number(amount).toLocaleString('es-CL') : String(amount)) + ' ' + currency; }\n// What arrived is a payment request or a confirmation ONLY if it came encrypted (the house could\n// not have read or altered it) and every field passes the same checks as when it is sent.\nfunction cobroDe(c, cifrado) {\n  if (!cifrado || !c || !c.body || typeof c.body !== 'object') return null;\n  const b = c.body, texto = (v, max) => typeof v === 'string' ? v.replace(/[\\u0000-\\u001f\\u007f-\\u009f\\u200b-\\u200f\\u202a-\\u202e\\u2060-\\u2064\\u2066-\\u2069\\ufeff]/g, '').trim().slice(0, max) : '';\n  if (typeof b.request_id !== 'string' || !/^[A-Za-z0-9._:-]{8,128}$/.test(b.request_id)) return null;\n  if (c.media === MEDIA_COBRO) {\n    const currency = b.currency === 'USD' ? 'USD' : b.currency === 'CLP' ? 'CLP' : null;\n    const amount = currency && montoNormal(b.amount, currency), rut = rutNormal(b.rut);\n    if (amount === null || !rut || !TIPOS_CUENTA[b.account_type] || !/^[0-9-]{1,30}$/.test(String(b.account_number || ''))) return null;\n    const name = texto(b.name, 120), bank = texto(b.bank, 60);\n    if (!name || !bank) return null;\n    return { kind: 'request', request_id: b.request_id, amount, currency, name, rut, bank, account_type: b.account_type, account_number: String(b.account_number), reference: texto(b.reference, 140) };\n  }\n  if (c.media === MEDIA_COBRO_CONF) { const ref = texto(b.bank_reference, 80); return ref ? { kind: 'confirmation', request_id: b.request_id, bank_reference: ref } : null; }\n  return null;\n}\n// The lines of the card, in this order; also what Copy details puts on the clipboard.\nfunction lineasCobro(c) {\n  const l = ['Amount: ' + montoBonito(c.amount, c.currency), 'To: ' + c.name, 'RUT: ' + rutBonito(c.rut), 'Bank: ' + c.bank, 'Account: ' + TIPOS_CUENTA[c.account_type] + ' ' + c.account_number];\n  if (c.reference) l.push('Reference: ' + c.reference);\n  return l;\n}\nconst PIE_COBRO = 'Nyx5 never touches the money. Pay from your own bank; this card only carries the details, encrypted, between the two of you.';\n// The card. `conf` is the bank reference once this request was confirmed (by me if it came in, by them if I sent it).\nfunction tarjetaCobro(id, c, mio, conf, meta) {\n  let h = '<div class=\"msg cobro ' + (mio ? 'mio' : 'suyo') + '\"><div class=\"cobro-t\">Payment request</div>';\n  for (const l of lineasCobro(c)) h += '<div class=\"cobro-l\">' + escapar(l) + '</div>';\n  if (conf) h += (mio ? '' : '<div class=\"cobro-l\" style=\"margin-top:.5rem\">Confirmation sent. Nyx5 does not move money: it only carries your confirmation.</div>') + '<div class=\"cobro-l\">' + escapar('Bank reference: ' + conf) + '</div>';\n  else if (!mio) h += '<div><button class=\"btn-min btn2\" data-copiar=\"' + escapar(id) + '\">Copy details</button><button class=\"btn-min btn2\" data-pagado=\"' + escapar(id) + '\">I paid \\u2014 confirm</button></div><div class=\"cobro-conf\" hidden><label>Bank reference</label><input maxlength=\"80\" autocomplete=\"off\"><button class=\"btn-min\" data-confirmar=\"' + escapar(id) + '\">Confirm</button></div>';\n  h += '<div class=\"cobro-pie\">' + PIE_COBRO + '</div><div class=\"meta\">' + escapar(meta) + '</div></div>';\n  return h;\n}\n// Requests seen in the open chat, by envelope id, for the buttons. Memory only: nothing is stored.\nconst COBROS = new Map();\nfunction puedeCobrar(dir) {\n  if (!dir || dir === ID.address || !ID.enc || ['libro', 'postmaster', 'verifica', 'tareas', 'qa'].includes(localDe(dir))) return Promise.resolve(false);\n  return tarjeta(dir).then((c) => !!c.enc && !c.group && !(c.custody && c.custody.keys === 'house') && soportaX25519(), () => false);\n}\nasync function enviarCobro(to, f) {\n  const currency = f.currency === 'USD' ? 'USD' : 'CLP';\n  const amount = montoNormal(f.amount, currency);\n  if (amount === null) throw new Error(currency === 'CLP' ? 'Amount must be a whole number of pesos.' : 'Amount must be a number of dollars with up to two decimals.');\n  const rut = rutNormal(f.rut);\n  if (!rut) throw new Error('RUT looks wrong (check the digit).');\n  if (!(await puedeCobrar(to))) throw new Error('That address cannot receive a payment request here');\n  const cobro = { request_id: crypto.randomUUID(), amount, currency, name: f.name.trim().slice(0, 120), rut, bank: f.bank.trim().slice(0, 60), account_type: TIPOS_CUENTA[f.account_type] ? f.account_type : 'checking', account_number: String(f.account_number).replace(/\\s+/g, '').slice(0, 30), reference: f.reference.trim().slice(0, 140) };\n  if (!/^[0-9-]{1,30}$/.test(cobro.account_number)) throw new Error('Account number: digits and dashes only');\n  return enviarSobre(to, { media: MEDIA_COBRO, body: cobro }, { extensions: { [EXT_COBRO]: { kind: 'request', request_id: cobro.request_id, currency } }, cifrado: 'required' });\n}\nasync function confirmarCobro(id, ref) {\n  const x = COBROS.get(id); if (!x) throw new Error('That request is no longer on screen');\n  const bank_reference = String(ref || '').trim().slice(0, 80);\n  if (!bank_reference) throw new Error('Bank reference');\n  const e = x.envelope;\n  return enviarSobre(e.from, { media: MEDIA_COBRO_CONF, body: { request_id: x.cobro.request_id, bank_reference } }, { type: 'result', thread: e.thread || e.id, in_reply_to: e.id, extensions: { [EXT_COBRO]: { kind: 'confirmation', request_id: x.cobro.request_id, currency: x.cobro.currency } }, cifrado: 'required' });\n}\nfunction hora(t) {\n  const d = new Date(t); if (isNaN(d)) return '';\n  return d.toDateString() === new Date().toDateString() ? d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : d.toLocaleDateString([], { day: 'numeric', month: 'short' });\n}\nconst ESTADOS = { delivered: 'delivered', queued: 'sending', inflight: 'sending', retrying: 'retrying', failed: 'not delivered', bounced: 'not delivered' };\n\n// ---------- screens ----------\nlet ACTUAL = null, CON = null;\nfunction pantalla(n) {\n  for (const s of ['entrar', 'invitacion', 'autorizar', 'chats', 'chat', 'cobrar', 'ajustes']) $(s).hidden = s !== n;\n  ACTUAL = n;\n  $('atras').hidden = !(n === 'chat' || n === 'cobrar');\n  $('tabs').hidden = !(n === 'chats' || n === 'ajustes');\n  $('tab-chats').classList.toggle('on', n === 'chats');\n  $('tab-ajustes').classList.toggle('on', n === 'ajustes');\n  if (n !== 'chat') { $('titulo').textContent = 'Nyx5'; $('titulo').classList.remove('dir'); }\n}\nfunction mostrarYo() { $('yo').hidden = false; $('yo').innerHTML = '<b>' + escapar(ID.local) + '</b><br>@' + escapar(ID.address.split('@')[1]); }\n\nasync function verChats() {\n  pantalla('chats');\n  pintarInstalar($('instalar'), false);\n  let lista = [];\n  try { lista = (await api('GET', '/conversations/' + ID.local)).conversations || []; } catch (e) { toast(e.message, true); }\n  if (!lista.length) { $('lista').innerHTML = '<div class=\"vacio\">No conversations yet.<br>Start one below.</div>'; return; }\n  $('lista').innerHTML = lista.map((c) => '<div class=\"fila\" data-con=\"' + escapar(c.with) + '\"><span class=\"quien\">' + escapar(c.with) + '</span>' + (c.pending ? '<span class=\"punto\">' + c.pending + '</span>' : '') + '<span class=\"cuando\">' + hora(c.last_at) + '</span></div>').join('');\n  for (const f of document.querySelectorAll('.fila')) f.onclick = () => abrirChat(f.dataset.con);\n}\nasync function abrirChat(dir) {\n  CON = dir;\n  pantalla('chat');\n  $('titulo').textContent = dir; $('titulo').classList.add('dir');\n  $('btn-tokens').hidden = true;\n  recibeTokens(dir).then((si) => { if (CON === dir) $('btn-tokens').hidden = !si; });\n  $('btn-cobrar').hidden = true;\n  puedeCobrar(dir).then((si) => { if (CON === dir) $('btn-cobrar').hidden = !si; });\n  $('feed').innerHTML = '<div class=\"vacio\"><span class=\"spin\"></span></div>';\n  await refrescarChat();\n}\nasync function refrescarChat() {\n  if (!CON) return;\n  let msgs = [];\n  try { msgs = (await api('GET', '/conversations/' + ID.local + '?with=' + encodeURIComponent(CON) + '&limit=200')).messages || []; } catch (e) { toast(e.message, true); return; }\n  const partes = [], pendientes = [], abiertos = [];\n  // A confirmation counts only for a request that is in THIS conversation and went the other way:\n  // they confirm what I sent, I confirm what they sent. Anything else stays as plain text.\n  const pedidos = new Map(), confirmados = new Map();\n  for (const m of msgs) { const a = await abrir(m); abiertos.push([m, a]); if (a.cobro && a.cobro.kind === 'request') pedidos.set(a.cobro.request_id, m.dir); }\n  for (const [m, a] of abiertos) if (a.cobro && a.cobro.kind === 'confirmation' && pedidos.has(a.cobro.request_id) && pedidos.get(a.cobro.request_id) !== m.dir) confirmados.set(a.cobro.request_id, a.cobro.bank_reference);\n  COBROS.clear();\n  for (const [m, a] of abiertos) {\n    const mio = m.dir === 'out';\n    if (!mio && !m.acked) pendientes.push(m.id);\n    const meta = [a.cifrado ? 'encrypted' : 'not encrypted', hora(m.at)];\n    if (mio) meta.push(ESTADOS[m.status] || m.status || 'sent');\n    const c = a.cobro;\n    if (c && c.kind === 'request') {\n      if (!mio) COBROS.set(m.id, { cobro: c, envelope: m.envelope, texto: lineasCobro(c).join('\\n') });\n      partes.push(tarjetaCobro(m.id, c, mio, confirmados.get(c.request_id) || null, meta.join(' · ')));\n      continue;\n    }\n    const texto = c && c.kind === 'confirmation' && confirmados.get(c.request_id) === c.bank_reference ? 'Bank reference: ' + c.bank_reference : a.texto;\n    partes.push('<div class=\"msg ' + (mio ? 'mio' : 'suyo') + (a.ilegible ? ' ilegible' : '') + '\">' + escapar(texto) + '<div class=\"meta\">' + escapar(meta.join(' · ')) + '</div></div>');\n  }\n  const feed = $('feed');\n  feed.innerHTML = partes.join('') || '<div class=\"vacio\">No messages yet.<br>Write below to start.</div>';\n  for (const b of feed.querySelectorAll('[data-copiar]')) b.onclick = () => { const x = COBROS.get(b.dataset.copiar); if (x) navigator.clipboard.writeText(x.texto).then(() => toast('Copied.'), () => toast('Select the details and copy them', true)); };\n  for (const b of feed.querySelectorAll('[data-pagado]')) b.onclick = () => { const f = b.parentElement.nextElementSibling; f.hidden = !f.hidden; if (!f.hidden) f.querySelector('input').focus(); };\n  for (const b of feed.querySelectorAll('[data-confirmar]')) b.onclick = async () => {\n    if (b.disabled) return; b.disabled = true;\n    try { await confirmarCobro(b.dataset.confirmar, b.previousElementSibling.value); toast('Confirmation sent. Nyx5 does not move money: it only carries your confirmation.'); await refrescarChat(); }\n    catch (e) { toast(e.message, true); b.disabled = false; }\n  };\n  feed.scrollTop = feed.scrollHeight;\n  if (pendientes.length) api('POST', '/mailbox/' + ID.local + '/ack', { ids: pendientes }).catch(() => {});\n}\n\n// Live delivery: the house holds this request open until something arrives (long poll).\nlet ESCUCHANDO = false;\nasync function escuchar() {\n  if (ESCUCHANDO) return; ESCUCHANDO = true;\n  let cursor = '';\n  try { const p = (await api('GET', '/mailbox/' + ID.local + '?limit=1')).messages || []; if (p.length) cursor = p[p.length - 1].received; } catch {}\n  for (;;) {\n    try {\n      const q = new URLSearchParams({ timeout: '25' }); if (cursor) q.set('since', cursor);\n      const { message } = await api('GET', '/mailbox/' + ID.local + '/wait?' + q);\n      if (!message) continue;\n      cursor = message.received;\n      const de = (message.envelope && message.envelope.from) || '';\n      if (ACTUAL === 'chat' && de === CON) await refrescarChat();\n      else if (ACTUAL === 'chats') await verChats();\n      avisar(de);\n    } catch { await dormir(4000); }\n  }\n}\nfunction avisar(de) {\n  if (!document.hidden || !('Notification' in window) || Notification.permission !== 'granted') return;\n  try { const n = new Notification('Nyx5', { body: 'New message from ' + de, tag: de }); n.onclick = () => { window.focus(); abrirChat(de); n.close(); }; } catch {}\n}\n\n// ---------- install and backup ----------\nconst esIOS = () => /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);\nconst instalada = () => (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) || navigator.standalone === true;\nlet promptInstalar = null;\nwindow.addEventListener('beforeinstallprompt', (e) => { e.preventDefault(); promptInstalar = e; });\nfunction pintarInstalar(el, siempre) {\n  if (instalada()) { el.hidden = !siempre; el.textContent = 'Installed on this device: your key stays here.'; return; }\n  if (esIOS()) { el.hidden = false; el.innerHTML = '<b>Keep your address.</b> On iPhone, Safari erases what a site stores after 7 days without a visit, and your key goes with it. Add Nyx5 to your Home Screen: tap Share, then Add to Home Screen.'; return; }\n  if (promptInstalar) {\n    el.hidden = false;\n    el.innerHTML = 'Install Nyx5 on this device so your key stays with you. <button class=\"btn-min\" id=\"btn-instalar\">Install</button>';\n    $('btn-instalar').onclick = async () => { const p = promptInstalar; promptInstalar = null; el.hidden = true; await p.prompt(); };\n    return;\n  }\n  el.hidden = !siempre;\n  el.textContent = 'Keep a backup of your key (below): it lives only on this device.';\n}\n\n// ---------- settings ----------\nasync function verAjustes() {\n  pantalla('ajustes');\n  $('aj-dir').textContent = ID.address;\n  $('aj-mcp').textContent = CASA + '/mcp';\n  pintarInstalar($('aj-instalar'), true);\n  $('txt-respaldo').hidden = true;\n  $('aj-saldo').textContent = '...';\n  saldo().then((b) => { $('aj-saldo').textContent = Number(b || 0).toLocaleString() + ' tokens'; }, () => { $('aj-saldo').textContent = 'Not available right now'; });\n  const cont = $('aj-conectados');\n  cont.innerHTML = '';\n  let dels = [];\n  try { dels = ((await api('GET', '/delegations/' + ID.local)).delegations || []).filter((d) => d.custody && d.custody.keys === 'house'); } catch { return; }\n  if (!dels.length) return;\n  const ahora = Date.now();\n  cont.innerHTML = '<label>Connected Claude</label>' + dels.map((d) => {\n    const vencida = d.valid_until && Date.parse(d.valid_until) <= ahora;\n    const estado = d.revoked ? 'Revoked' : vencida ? 'Expired' : 'Active until ' + new Date(d.valid_until).toLocaleDateString();\n    const vivo = !d.revoked && !vencida;\n    return '<div class=\"conectado\"><div class=\"mono\">' + escapar(d.address) + '</div><div class=\"estado\">' + escapar(estado) + '</div>' + (vivo ? '<button class=\"btn-min btn-peligro\" data-rev=\"' + escapar(d.address) + '\">Revoke</button>' : '') + '</div>';\n  }).join('');\n  for (const b of cont.querySelectorAll('[data-rev]')) b.onclick = async () => {\n    const dir = b.dataset.rev;\n    if (!confirm('Revoke ' + dir + '? Claude stops working through it right away, and its key is deleted.')) return;\n    b.disabled = true;\n    try { await api('POST', '/agents/' + encodeURIComponent(dir.split('@')[0]) + '/revoke', {}); toast('Revoked'); } catch (e) { toast(e.message, true); }\n    verAjustes();\n  };\n}\n\n// ---------- authorizing a Claude connector ----------\n// The invitation page: one link, sent by someone, that explains the three taps in Claude.\nfunction verInvitacion() {\n  pantalla('invitacion');\n  if (INVITE.error) {\n    $('inv-pasos').hidden = true; $('inv-error').hidden = false;\n    $('inv-error').textContent = INVITE.error === 'used' ? 'This invitation was already used. Ask for a new one.' : 'This invitation does not exist or has expired. Ask for a new one.';\n    return;\n  }\n  const n = nombreDe(INVITE.inviter);\n  $('inv-titulo').textContent = n + ' invited you to Nyx5';\n  $('inv-sub').textContent = 'Nyx5 gives your Claude an address of its own, so it can talk with the Claude of ' + n + ' directly. It takes a minute.';\n  $('inv-url').textContent = INVITE.connector_url;\n  $('inv-frase').textContent = 'Write to ' + (INVITE.greet || n) + ': hi';\n}\n// Authorizing a connector is ONE screen, even for someone who has no address yet.\nfunction verAutorizar() {\n  pantalla('autorizar');\n  $('oa-cliente').textContent = OAUTH.client_name || 'Claude';\n  const inv = OAUTH.invite;\n  $('oa-nuevo').hidden = !!ID;\n  if (!ID) $('oa-nombre').value = (inv && inv.name_hint) || '';\n  const pintarSub = () => { $('oa-sub').textContent = 'claude.' + (ID ? ID.local : (limpio($('oa-nombre').value) || 'yourname')) + '@' + DOMINIO; };\n  pintarSub();\n  $('oa-nombre').oninput = pintarSub;\n  if (inv) {\n    const n = nombreDe(inv.inviter);\n    $('oa-invitado').hidden = false;\n    $('oa-invitado').textContent = n + ' invited you. ' + (inv.inviter_claude ? n + ' and the Claude of ' + n + ' will be able to write to your Claude, and yours to theirs.' : n + ' will be able to write to your Claude.');\n    document.querySelector('input[name=quien][value=lista]').checked = true;\n    $('oa-lista').hidden = false;\n    $('oa-lista').value = [inv.inviter, inv.inviter_claude, ...(inv.contacts || [])].filter(Boolean).join('\\n');\n  }\n  $('oa-dias').textContent = OAUTH.days;\n  $('oa-host').textContent = OAUTH.redirect_host;\n  $('oa-loopback').hidden = !OAUTH.loopback;\n  for (const r of document.querySelectorAll('input[name=quien]')) r.onchange = () => { $('oa-lista').hidden = r.value !== 'lista' || !r.checked; };\n}\nconst pedido = () => ({ response_type: 'code', client_id: OAUTH.client_id, redirect_uri: OAUTH.redirect_uri, state: OAUTH.state || undefined, code_challenge: OAUTH.code_challenge, code_challenge_method: 'S256', resource: OAUTH.resource });\n$('btn-permitir').onclick = async () => {\n  const btn = $('btn-permitir'); btn.disabled = true; btn.innerHTML = '<span class=\"spin\"></span> Connecting...';\n  try {\n    if (!ID) {\n      const local = limpio($('oa-nombre').value);\n      if (!local) throw new Error('Type a name');\n      await registrar(local, undefined);\n      mostrarYo();\n    }\n    const prep = await api('POST', '/oauth/prepare', pedido());\n    const delegacion = await firmaObjeto({ by: ID.address, address: prep.address, sig: prep.sig, scope: prep.scope, valid_until: prep.valid_until, issued: iso() });\n    const quien = document.querySelector('input[name=quien]:checked').value;\n    const allowlist = quien === 'open' ? 'open' : quien === 'lista' ? $('oa-lista').value.split(/[\\s,]+/).filter(Boolean) : [];\n    const r = await api('POST', '/oauth/approve', { ...pedido(), delegation: delegacion, allowlist });\n    btn.innerHTML = 'Connected. Going back...';\n    location.href = r.redirect;\n  } catch (e) { toast(e.message, true); btn.disabled = false; btn.textContent = 'Connect'; }\n};\n$('btn-negar').onclick = () => {\n  const u = new URL(OAUTH.redirect_uri);\n  u.searchParams.set('error', 'access_denied');\n  if (OAUTH.state) u.searchParams.set('state', OAUTH.state);\n  location.href = u.toString();\n};\n\n// ---------- events ----------\n$('nombre').addEventListener('input', (e) => { const v = e.target.value.trim().toLowerCase().replace(/[^a-z0-9._-]/g, ''); $('preview').textContent = (v || 'yourname') + '@' + DOMINIO; });\n$('btn-entrar').onclick = async () => {\n  const local = $('nombre').value.trim().toLowerCase().replace(/[^a-z0-9._-]/g, '');\n  if (!local) return toast('Type a name', true);\n  const btn = $('btn-entrar'); btn.disabled = true; btn.innerHTML = '<span class=\"spin\"></span> Creating...';\n  try { await registrar(local, params.get('invite') || undefined); toast('Done. You have an address'); await dentro(); }\n  catch (err) { toast(err.message, true); btn.disabled = false; btn.textContent = 'Create my address'; }\n};\n$('ir-importar').onclick = (e) => { e.preventDefault(); $('entrar-form').hidden = true; $('importar').hidden = false; };\n$('ir-crear').onclick = (e) => { e.preventDefault(); $('entrar-form').hidden = false; $('importar').hidden = true; };\n$('btn-importar').onclick = async () => {\n  const btn = $('btn-importar'); btn.disabled = true;\n  try { await importar($('txt-importar').value.trim()); $('txt-importar').value = ''; toast('Address restored'); await dentro(); }\n  catch (err) { toast(err.message, true); btn.disabled = false; }\n};\n$('btn-enviar').onclick = async () => {\n  const t = $('texto').value.trim(); if (!t || !CON) return;\n  const btn = $('btn-enviar'); btn.disabled = true;\n  if ('Notification' in window && Notification.permission === 'default') { try { Notification.requestPermission(); } catch {} }\n  try { await enviar(CON, t); $('texto').value = ''; $('texto').style.height = 'auto'; await refrescarChat(); }\n  catch (err) { toast(err.message, true); }\n  btn.disabled = false;\n};\n$('texto').addEventListener('input', (e) => { e.target.style.height = 'auto'; e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px'; });\n$('texto').addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); $('btn-enviar').click(); } });\n// Disabled while it works: a second tap during a payment must not become a second payment.\n$('btn-tokens').onclick = async () => {\n  const dir = CON, btn = $('btn-tokens'); if (!dir || btn.disabled) return;\n  btn.disabled = true;\n  try { await enviarTokens(dir); } finally { btn.disabled = false; }\n};\nasync function enviarTokens(dir) {\n  let tengo = null; try { tengo = await saldo(); } catch {}\n  const r = prompt('How many tokens do you want to send to ' + dir + '?' + (tengo != null ? ' You have ' + tengo.toLocaleString() + '.' : ''));\n  if (r === null) return;\n  // Only whole numbers, with or without thousands separators: 1000, 1.000, 1,000, 1 000.\n  // \"1,5\", \"1e3\", \"0x10\" or \"-5\" are refused instead of being read as something else.\n  const t = String(r).replace(/\\s/g, '');\n  if (!/^(\\d+|\\d{1,3}([.,]\\d{3})+)$/.test(t)) return toast('Write a whole number of tokens', true);\n  const n = Number(t.replace(/[.,]/g, ''));\n  if (!Number.isSafeInteger(n) || n <= 0) return toast('Write a whole number of tokens', true);\n  if (tengo != null && n > tengo) return toast('You have ' + tengo.toLocaleString() + ' tokens', true);\n  if (!confirm('Send ' + n.toLocaleString() + ' tokens to ' + dir + '? It cannot be undone.')) return;\n  try { await pagar(dir, n); toast('Sent. The receipt arrives from libro@' + DOMINIO); } catch (e) { toast(e.message, true); }\n}\n$('btn-cobrar').onclick = () => {\n  if (!CON) return;\n  pantalla('cobrar');\n  $('co-para').textContent = CON;\n  for (const id of ['co-monto', 'co-nombre', 'co-rut', 'co-banco', 'co-cuenta', 'co-ref']) $(id).value = '';\n  $('co-moneda').value = 'CLP'; $('co-tipo').value = 'checking';\n  $('co-monto-l').textContent = 'Amount (CLP)';\n  $('btn-cobro-enviar').disabled = true;\n};\nconst cobroCompleto = () => ['co-monto', 'co-nombre', 'co-rut', 'co-banco', 'co-cuenta'].every((id) => $(id).value.trim());\nfor (const id of ['co-monto', 'co-nombre', 'co-rut', 'co-banco', 'co-cuenta']) $(id).addEventListener('input', () => { $('btn-cobro-enviar').disabled = !cobroCompleto(); });\n$('co-moneda').onchange = () => { $('co-monto-l').textContent = 'Amount (' + $('co-moneda').value + ')'; };\n$('btn-cobro-enviar').onclick = async () => {\n  const dir = CON, btn = $('btn-cobro-enviar'); if (!dir || btn.disabled) return;\n  btn.disabled = true;\n  try {\n    await enviarCobro(dir, { amount: $('co-monto').value, currency: $('co-moneda').value, name: $('co-nombre').value, rut: $('co-rut').value, bank: $('co-banco').value, account_type: $('co-tipo').value, account_number: $('co-cuenta').value, reference: $('co-ref').value });\n    toast('Request sent, encrypted. You will get a message when they confirm.');\n    await abrirChat(dir);\n  } catch (e) { toast(e.message, true); btn.disabled = !cobroCompleto(); }\n};\n$('btn-nuevo').onclick = async () => {\n  const d = (prompt('Who do you want to write to? (full address)') || '').trim().toLowerCase();\n  if (!d) return;\n  if (!/^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(d)) return toast('That is not an address', true);\n  try { await tarjeta(d); abrirChat(d); } catch (err) { toast(err.message, true); }\n};\n$('atras').onclick = () => { if (ACTUAL === 'cobrar' && CON) return abrirChat(CON); CON = null; verChats(); };\n$('tab-chats').onclick = () => verChats();\n$('tab-ajustes').onclick = () => verAjustes();\n$('btn-copiar-dir').onclick = () => navigator.clipboard.writeText(ID.address).then(() => toast('Copied'), () => {});\n$('btn-copiar-mcp').onclick = () => navigator.clipboard.writeText(CASA + '/mcp').then(() => toast('Copied'), () => {});\n$('btn-inv-copiar').onclick = () => navigator.clipboard.writeText(INVITE.connector_url).then(() => toast('Copied. Now open the Claude app'), () => toast('Select the link and copy it', true));\n$('btn-invitar').onclick = async () => {\n  const nombre = limpio(prompt('Their name (optional, one word)') || '');\n  try {\n    const r = await api('POST', '/contact-invites', { name: nombre || undefined });\n    $('inv-creado').hidden = false; $('inv-creado').textContent = r.link;\n    const texto = 'Join me on Nyx5 so our Claudes can talk: ' + r.link;\n    if (navigator.share) { try { await navigator.share({ text: texto }); } catch {} }\n    else navigator.clipboard.writeText(r.link).then(() => toast('Link copied'), () => {});\n  } catch (e) { toast(e.message, true); }\n};\n$('btn-respaldo').onclick = () => {\n  const t = $('txt-respaldo');\n  t.hidden = !t.hidden;\n  t.value = JSON.stringify({ address: ID.address, keys: { sig: ID.sig, sigPriv: ID.sigPriv, enc: ID.enc, encPriv: ID.encPriv } }, null, 1);\n  if (!t.hidden) { t.focus(); t.select(); }\n};\n\n// ---------- start ----------\nasync function dentro() {\n  await asegurarCifrado();\n  mostrarYo();\n  if (OAUTH) return verAutorizar();\n  escuchar();\n  const to = (params.get('to') || '').toLowerCase();\n  if (to) return abrirChat(to);\n  return verChats();\n}\n(async () => {\n  try { if (navigator.storage && navigator.storage.persist) navigator.storage.persist().catch(() => {}); } catch {}\n  await casa();\n  $('preview').textContent = (params.get('name') || 'yourname') + '@' + DOMINIO;\n  if (INVITE) { await cargar(); return verInvitacion(); }\n  if (await cargar()) return dentro();\n  if (OAUTH) return verAutorizar();\n  pantalla('entrar');\n})();\n</script>\n</body>\n</html>\n";
